import math


def _norm(v):
    # Canonical form: -0.0 collapses to 0.0 (it equals 0.0) and integral floats
    # collapse to ints (they equal the int), so both hit the same hash/==
    # bucket as their int counterpart. Floats that are not integral (and
    # inf/nan) stay floats; nan is pinned to a unique sentinel so it is
    # treated as non-equal to everything, matching `==`.
    if isinstance(v, float):
        if math.isnan(v):
            return ("__nan__",)
        if math.isinf(v):
            return ("__inf__", v > 0)
        if v == 0.0:
            return 0
        if v.is_integer() and abs(v) < 2**53:
            return int(v)
        if v.is_integer():
            # Large integral floats: keep as float but exclude the value from
            # collision with ints of the same value via a tag.
            return ("__float_int__", v)
        return v
    if isinstance(v, dict):
        return tuple(sorted((k, _norm(x)) for k, x in v.items()))
    if isinstance(v, (list, tuple)):
        return tuple(_norm(x) for x in v)
    if isinstance(v, (str, int, bool)) or v is None:
        return v
    return repr(v)


def _key(record, key):
    return _norm(key(record) if key is not None else record)


def dedupe(records, key=None):
    seen = set()
    out = []
    for r in records:
        k = _key(r, key)
        if k not in seen:
            seen.add(k)
            out.append(r)
    return out
