import math

# Sentinel-wrapped tags for floats whose repr-form would collide with real
# JSON values or whose == semantics differ from plain equality.
_NAN = object()
_INF_POS = object()
_INF_NEG = object()
_LARGE_INT_FLOAT = object()


def _norm(v):
    # Canonicalize for equality so that ==-equal values hash identically and
    # stay distinguishable from non-equal values:
    # - nan is not equal to anything (incl. itself); pin it to a unique tag.
    # - inf is not equal to anything else; pin it to two unique tags.
    # - -0.0 == 0.0; collapse to int 0.
    # - integral floats < 2**53 == the same int; collapse to int.
    # - integral floats >= 2**53: keep as float but tag so they don't collide
    #   with an int of the same value (which is == to the float).
    # - dicts/lists become tuples (hashable); dicts are sorted by key.
    if isinstance(v, float):
        if math.isnan(v):
            return (_NAN,)
        if math.isinf(v):
            return (_INF_POS if v > 0 else _INF_NEG,)
        if v == 0.0:
            return 0
        if v.is_integer():
            if abs(v) < 2**53:
                return int(v)
            return (_LARGE_INT_FLOAT, v)
        return v
    if isinstance(v, dict):
        return tuple(sorted(((k, _norm(x)) for k, x in v.items()),
                            key=lambda kv: repr(kv[0])))
    if isinstance(v, (list, tuple)):
        return tuple(_norm(x) for x in v)
    if isinstance(v, (str, int, bool)) or v is None:
        return v
    return repr(v)


def dedupe(records, key=None):
    seen = set()
    out = []
    if key is None:
        for r in records:
            k = _norm(r)
            if k not in seen:
                seen.add(k)
                out.append(r)
    else:
        for r in records:
            k = _norm(key(r))
            if k not in seen:
                seen.add(k)
                out.append(r)
    return out
