{"content":""""Remove duplicate records, keeping the first occurrence."""

import math

# Tag objects for compound containers so that the normalized bucket differs
# between list and tuple (they are never ==) and between dict and either.
_LIST = object()
_TUPLE = object()
_DICT = object()
_NAN = object()
_INF_POS = object()
_INF_NEG = object()
_LARGE_INT_FLOAT = object()
_OTHER = object()

_INT_FLOAT_LIMIT = 2**53


def _norm(v):
    # Canonicalize a JSON-like value (dicts, lists, scalars) into a hashable
    # form where equal values map to identical forms, matching Python ==.
    # - nan is not equal to anything (incl. itself); pin it to a unique tag.
    # - inf is not equal to anything else; pin to two unique tags.
    # - -0.0 == 0.0; collapse to int 0.
    # - integral floats == the same int: collapse to int (tagged beyond 2**53).
    # - dicts normalize to a sorted (key, value) tuple so key order does not
    #   matter; lists/tuples keep order and are tagged distinctly.
    if isinstance(v, bool):
        # bool is a subclass of int; keep as-is (True == 1 already).
        return v
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        if math.isnan(v):
            return (_NAN,)
        if math.isinf(v):
            return (_INF_POS if v > 0 else _INF_NEG,)
        if v == 0.0:
            return 0
        if v.is_integer():
            if abs(v) < _INT_FLOAT_LIMIT:
                return int(v)
            return (_LARGE_INT_FLOAT, v)
        return v
    if isinstance(v, str) or v is None:
        return v
    if isinstance(v, list):
        return (_LIST, tuple(_norm(x) for x in v))
    if isinstance(v, tuple):
        return (_TUPLE, tuple(_norm(x) for x in v))
    if isinstance(v, dict):
        items = []
        for k, x in v.items():
            nk = _norm(k)
            items.append((nk, _norm(x)))
        items.sort(key=lambda kv: _sort_key(kv[0]))
        return (_DICT, tuple(items))
    # Non-JSON values (e.g. from custom key functions): fall back to repr
    # so they remain hashable and comparable.
    return (_OTHER, repr(v))


def _sort_key(nk):
    if isinstance(nk, str):
        return (0, nk)
    return (1, repr(nk))


def dedupe(records, key=None):
    seen = set()
    out = []
    if key is None:
        for r in records:
            k = _norm(r)
            if k not in seen:
                seen.add(k)
                out.append(r)
    else:
        for r in records:
            k = _norm(key(r))
            if k not in seen:
                seen.add(k)
                out.append(r)
    return out
